type completionUsageInput struct {
	PartID   string `json:"part_id"`
	Quantity int64  `json:"quantity"`
}

// CompleteRepair implements the project-owned work_order.complete_repair Handler.
func CompleteRepair(ctx context.Context, caps capabilities.CompleteRepairCapabilities, input capabilities.CompleteRepairInput) (capabilities.CompleteRepairOutput, error) {
	if caps.Execution == nil || caps.WorkOrder == nil || caps.SparePart == nil || caps.InventoryUsage == nil {
		return capabilities.CompleteRepairOutput{}, fmt.Errorf("work_order.complete_repair.capability_unavailable")
	}
	principal := caps.Execution.Principal()
	order, err := caps.WorkOrder.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.CompleteRepairOutput{}, err
	}
	if order.Status != schema.WorkOrderStatus("in_repair") {
		return capabilities.CompleteRepairOutput{}, fmt.Errorf("work_order.complete_repair.invalid_transition")
	}
	if order.AssigneeUserID == nil || string(order.AssigneeUserID.ID()) != principal.UserID {
		return capabilities.CompleteRepairOutput{}, fmt.Errorf("work_order.complete_repair.not_assignee")
	}
	grossCents, err := parseMoneyCents(string(input.GrossAmount))
	if err != nil || grossCents < 0 {
		return capabilities.CompleteRepairOutput{}, fmt.Errorf("work_order.complete_repair.invalid_amount")
	}
	var requested []completionUsageInput
	if err = json.Unmarshal([]byte(input.UsageJson), &requested); err != nil || len(requested) == 0 || len(requested) > 200 {
		return capabilities.CompleteRepairOutput{}, fmt.Errorf("work_order.complete_repair.invalid_usage")
	}
	wanted := make(map[string]int64, len(requested))
	ids := make([]schema.SparePartID, 0, len(requested))
	for _, line := range requested {
		if line.PartID == "" || line.Quantity <= 0 {
			return capabilities.CompleteRepairOutput{}, fmt.Errorf("work_order.complete_repair.invalid_usage")
		}
		if _, exists := wanted[line.PartID]; exists {
			return capabilities.CompleteRepairOutput{}, fmt.Errorf("work_order.complete_repair.duplicate_part")
		}
		wanted[line.PartID] = line.Quantity
		ids = append(ids, schema.SparePartID(line.PartID))
	}
	query := data.NewSparePartQuery().WhereIDIn(ids[0], ids[1:]...).OrderByIDAscending().Page(1, 200)
	parts, err := caps.SparePart.List(ctx, query)
	if err != nil {
		return capabilities.CompleteRepairOutput{}, err
	}
	if len(parts) != len(requested) {
		return capabilities.CompleteRepairOutput{}, fmt.Errorf("work_order.complete_repair.part_not_found")
	}
	partMutations := make([]data.SparePartUpdateMutation, 0, len(parts))
	usages := make([]schema.CreateInventoryUsage, 0, len(parts))
	now := time.Now().UTC()
	for _, part := range parts {
		qty, ok := wanted[string(part.ID)]
		if !ok {
			return capabilities.CompleteRepairOutput{}, fmt.Errorf("work_order.complete_repair.part_not_found")
		}
		if part.StockQty < qty {
			return capabilities.CompleteRepairOutput{}, fmt.Errorf("work_order.complete_repair.insufficient_stock")
		}
		unitCents, parseErr := parseMoneyCents(string(part.UnitPrice))
		if parseErr != nil || unitCents < 0 || (unitCents > 0 && qty > (1<<63-1)/unitCents) {
			return capabilities.CompleteRepairOutput{}, fmt.Errorf("work_order.complete_repair.invalid_part_price")
		}
		lineAmount := formatMoneyCents(unitCents * qty)
		partMutations = append(partMutations, data.NewSparePartUpdate(part.ID).SetStockQty(part.StockQty-qty).RequireStockQtyEqual(part.StockQty, "work_order.complete_repair.insufficient_stock").WithExpectedUpdatedAt(part.UpdatedAt))
		usages = append(usages, schema.CreateInventoryUsage{WorkOrderID: schema.NewInventoryUsageWorkOrderIDReference(order.ID), PartID: schema.NewInventoryUsagePartIDReference(part.ID), Quantity: qty, UnitPriceSnapshot: schema.InventoryUsageUnitPriceSnapshot(part.UnitPrice), LineAmount: schema.InventoryUsageLineAmount(lineAmount), TechnicianUserID: principal.UserID, OccurredAt: now})
	}
	if _, err = caps.SparePart.ConditionalUpdateBatch(ctx, partMutations); err != nil {
		return capabilities.CompleteRepairOutput{}, err
	}
	created, err := caps.InventoryUsage.CreateBatch(ctx, usages)
	if err != nil {
		return capabilities.CompleteRepairOutput{}, err
	}
	updated, err := caps.WorkOrder.ConditionalUpdate(ctx, data.NewWorkOrderUpdate(order.ID).SetGrossAmount(input.GrossAmount).SetCompletedAt(now).SetStatus(schema.WorkOrderStatus("completed")).RequireStatusEqual(schema.WorkOrderStatus("in_repair"), "work_order.complete_repair.conflict").RequireAssigneeUserIDEqual(*order.AssigneeUserID, "work_order.complete_repair.not_assignee").WithExpectedUpdatedAt(order.UpdatedAt))
	if err != nil {
		return capabilities.CompleteRepairOutput{}, err
	}
	return capabilities.CompleteRepairOutput{WorkOrderID: updated.ID, Status: schema.WorkOrderCompleteRepairStatusCompleted, UsageCount: int64(len(created))}, nil
}
