package actions

import (
	"context"
	capabilities "example.com/domainry/m2-fieldservice/generated/capabilities"
	"example.com/domainry/m2-fieldservice/generated/data"
	"example.com/domainry/m2-fieldservice/generated/schema"
	"time"
)

// ScanOverdueWorkOrders implements the project-owned reminder_delivery.scan_overdue_work_orders Handler.
func ScanOverdueWorkOrders(ctx context.Context, caps capabilities.ScanOverdueWorkOrdersCapabilities, input capabilities.ScanOverdueWorkOrdersInput) (capabilities.ScanOverdueWorkOrdersOutput, error) {
	if caps.Execution == nil || caps.WorkOrder == nil || caps.ReminderDelivery == nil || caps.Notifications == nil {
		return capabilities.ScanOverdueWorkOrdersOutput{}, businessError("reminder_delivery.scan_overdue_work_orders.capability_unavailable")
	}
	if input.RunAt.IsZero() {
		return capabilities.ScanOverdueWorkOrdersOutput{}, businessError("reminder_delivery.scan_overdue_work_orders.invalid_run_at")
	}
	orders, err := caps.WorkOrder.List(ctx, data.NewWorkOrderQuery().WhereStatusEqual(schema.WorkOrderStatus("dispatched")).WhereDispatchedAtLessThanOrEqual(input.RunAt.Add(-48*time.Hour)).OrderByIDAscending().Page(1, 200))
	if err != nil {
		return capabilities.ScanOverdueWorkOrdersOutput{}, err
	}
	businessDate := time.Date(input.RunAt.Year(), input.RunAt.Month(), input.RunAt.Day(), 0, 0, 0, 0, input.RunAt.Location())
	queries := make([]data.ReminderDeliveryQuery, 0, len(orders))
	keys := make([]string, 0, len(orders))
	for _, order := range orders {
		key := fmt.Sprintf("%s:%s", order.ID, businessDate.Format("2006-01-02"))
		keys = append(keys, key)
		queries = append(queries, data.NewReminderDeliveryQuery().WhereDedupeKeyEqual(key).Page(1, 1))
	}
	if len(queries) == 0 {
		return capabilities.ScanOverdueWorkOrdersOutput{}, nil
	}
	exists, err := caps.ReminderDelivery.ExistsBatch(ctx, queries)
	if err != nil {
		return capabilities.ScanOverdueWorkOrdersOutput{}, err
	}
	creates := make([]schema.CreateReminderDelivery, 0, len(orders))
	intents := make([]capabilities.ScanOverdueWorkOrdersNotificationIntent, 0, len(orders))
	for index, order := range orders {
		if exists[index] || order.AssigneeUserID == nil {
			continue
		}
		recipient := string(order.AssigneeUserID.ID())
		ticketNo := order.TicketNo
		creates = append(creates, schema.CreateReminderDelivery{DedupeKey: keys[index], WorkOrderID: schema.NewReminderDeliveryWorkOrderIDReference(order.ID), BusinessDate: businessDate, RecipientUserID: recipient, SentAt: input.RunAt})
		intents = append(intents, capabilities.ScanOverdueWorkOrdersNotificationIntent{EventType: "work_order.overdue", SourceEventID: "overdue:" + keys[index], RecipientUserIDs: []string{recipient}, Surface: "business_workspace", SubjectObjectKey: "work_order", SubjectRecordID: string(order.ID), SubjectVersion: order.UpdatedAt, DedupeKey: "overdue:" + keys[index], OccurredAt: input.RunAt, Variables: []capabilities.ScanOverdueWorkOrdersNotificationVariable{{Key: "ticket_no", StringValue: &ticketNo}}})
	}
	if len(creates) == 0 {
		return capabilities.ScanOverdueWorkOrdersOutput{}, nil
	}
	created, err := caps.ReminderDelivery.CreateBatch(ctx, creates)
	if err != nil {
		return capabilities.ScanOverdueWorkOrdersOutput{}, err
	}
	if _, err = caps.Notifications.DispatchBatch(ctx, intents); err != nil {
		return capabilities.ScanOverdueWorkOrdersOutput{}, err
	}
	return capabilities.ScanOverdueWorkOrdersOutput{CreatedCount: int64(len(created))}, nil
}
// This file is initial project-owned business source. Domainry will never overwrite it.
package actions

import (
	"context"
	"crypto/sha256"
	capabilities "example.com/domainry/m2-fieldservice/generated/capabilities"
	"example.com/domainry/m2-fieldservice/generated/schema"
	"time"
)

// SubmitServiceRequest implements the project-owned work_order.submit_service_request Handler.
func SubmitServiceRequest(ctx context.Context, caps capabilities.SubmitServiceRequestCapabilities, input capabilities.SubmitServiceRequestInput) (capabilities.SubmitServiceRequestOutput, error) {
	if caps.Execution == nil || caps.Device == nil || caps.WorkOrder == nil {
		return capabilities.SubmitServiceRequestOutput{}, businessError("work_order.submit_service_request.capability_unavailable")
	}
	principal := caps.Execution.Principal()
	if !principal.Known || principal.ActiveBusinessProfile == nil || principal.ActiveBusinessProfile.BindingKey != "fieldservice_customer" {
		return capabilities.SubmitServiceRequestOutput{}, businessError("work_order.submit_service_request.profile_required")
	}
	if input.RequestID == "" || input.FaultDescription == "" || input.ExpectedVisitAt.IsZero() {
		return capabilities.SubmitServiceRequestOutput{}, businessError("work_order.submit_service_request.invalid_input")
	}
	device, err := caps.Device.Get(ctx, input.DeviceID)
	if err != nil {
		return capabilities.SubmitServiceRequestOutput{}, err
	}
	if string(device.CustomerID.ID()) != principal.ActiveBusinessProfile.RecordID {
		return capabilities.SubmitServiceRequestOutput{}, businessError("work_order.submit_service_request.device_forbidden")
	}
	now := time.Now().UTC()
	digest := sha256.Sum256([]byte(principal.UserID + ":" + input.RequestID))
	ticketNo := fmt.Sprintf("WO-%x", digest[:8])
	created, err := caps.WorkOrder.Create(ctx, schema.CreateWorkOrder{
		DeviceID:                 schema.NewWorkOrderDeviceIDReference(input.DeviceID),
		ExpectedVisitAt:          input.ExpectedVisitAt,
		FaultDescription:         input.FaultDescription,
		Status:                   schema.WorkOrderStatus("submitted"),
		SubmittedAt:              now,
		TicketNo:                 ticketNo,
		WarrantyEligibleSnapshot: device.WarrantyEligible,
	})
	if err != nil {
		return capabilities.SubmitServiceRequestOutput{}, err
	}
	return capabilities.SubmitServiceRequestOutput{WorkOrderID: created.ID, TicketNo: created.TicketNo, Status: schema.WorkOrderSubmitServiceRequestStatusSubmitted}, nil
}

