	"testing"
	"time"
)

func TestSubmitServiceRequestCreatesOwnedTicket(t *testing.T) {
	devices := &submitDeviceStore{device: schema.Device{ID: "device-1", CustomerID: schema.NewDeviceCustomerIDReference("customer-1"), WarrantyEligible: true}}
